/**
 * Passage 1: the drawing and a lean block-in over a warm earth ground.
 *
 * The tubes go on the palette and the piles for the whole painting are mixed from them.
 * Then the composition is drawn in thin umber with a small round brush (the table's
 * back edge, the jug, the circles of the flower heads), and every mass is scrubbed in
 * with a big flat in thinned paint: light wall at the upper left where the window light
 * falls, the olive wall darkening to the right, the cloth, the jug, the dark of the
 * bouquet. The warm ground stays open in the gaps, to glow through the knife work.
 */

// The tubes. Every color in the painting is mixed from these eight.
palette('white', '#f6f2e7');
palette('cadYellow', '#f4c20d');
palette('ochre', '#c48a2c');
palette('cadRed', '#d8381c');
palette('alizarin', '#7a1830');
palette('ultra', '#22307f');
palette('viridian', '#17644f');
palette('umber', '#4a2e1f');

// Wall: lightest where the window light lands, through ochre and olive to the shaded right.
palette('wallLight', mix(['white', 7], ['ochre', 1], ['cadRed', 0.12]));
palette('wallGold', mix(['white', 3.5], ['ochre', 1.3], ['cadRed', 0.14], ['umber', 0.1]));
palette(
  'wallOlive',
  mix(['white', 2.2], ['ochre', 1], ['umber', 0.55], ['viridian', 0.1], ['alizarin', 0.06]),
);
palette(
  'wallDeep',
  mix(
    ['umber', 1.1],
    ['ochre', 0.7],
    ['white', 0.9],
    ['viridian', 0.16],
    ['alizarin', 0.12],
    ['ultra', 0.1],
  ),
);
palette(
  'wallShadow',
  mix(['umber', 1], ['white', 0.9], ['ultra', 0.3], ['alizarin', 0.22], ['ochre', 0.3]),
);

// Cloth: warm white in the light, blue-grey turning to blue-violet in the shade.
palette('clothLight', mix(['white', 10], ['cadYellow', 0.25], ['ochre', 0.15]));
palette('clothMid', mix(['white', 6], ['ultra', 0.25], ['ochre', 0.3], ['alizarin', 0.06]));
palette('clothShade', mix(['white', 3.5], ['ultra', 0.55], ['alizarin', 0.18], ['umber', 0.15]));
palette('clothDeep', mix(['white', 1.5], ['ultra', 0.8], ['alizarin', 0.35], ['umber', 0.3]));

// The jug: a cobalt glaze, deep on the shadow side, with a cool white highlight.
palette('cobaltDeep', mix(['ultra', 2], ['alizarin', 0.25], ['umber', 0.35], ['white', 0.15]));
palette('cobalt', mix(['ultra', 2], ['white', 0.7], ['viridian', 0.12]));
palette('cobaltLight', mix(['ultra', 1], ['white', 1.6], ['viridian', 0.08]));
palette('jugGlint', mix(['white', 8], ['ultra', 0.3]));
palette('jugWarm', mix(['ultra', 1], ['white', 1.2], ['alizarin', 0.3], ['ochre', 0.45]));

// Poppies: three families, each a dark, a body, and a light.
palette('redDark', mix(['alizarin', 2], ['cadRed', 1], ['umber', 0.2]));
palette('red', mix(['cadRed', 3], ['alizarin', 0.5]));
palette('redLight', mix(['cadRed', 3], ['cadYellow', 0.5], ['white', 0.3]));
palette('orangeDark', mix(['cadRed', 2], ['alizarin', 0.4], ['ochre', 0.6]));
palette('orange', mix(['cadRed', 2], ['cadYellow', 1.4]));
palette('orangeLight', mix(['cadYellow', 2], ['cadRed', 0.7], ['white', 0.6]));
palette('coralDark', mix(['cadRed', 1.5], ['alizarin', 0.7], ['white', 0.4]));
palette('coral', mix(['cadRed', 2], ['white', 1.1], ['alizarin', 0.25]));
palette('coralLight', mix(['white', 2.4], ['cadRed', 1], ['cadYellow', 0.3]));

// Greens: the glaucous grey-green of poppy leaves, a dark for the depths, a stem green.
palette('leafDark', mix(['viridian', 1.2], ['umber', 1.3], ['ultra', 0.35]));
palette('leaf', mix(['viridian', 1], ['ochre', 1], ['umber', 0.55], ['white', 0.6]));
palette(
  'leafGrey',
  mix(['white', 2], ['viridian', 0.6], ['ochre', 0.6], ['umber', 0.3], ['ultra', 0.12]),
);
palette('stem', mix(['viridian', 0.8], ['ochre', 1.2], ['umber', 0.5], ['white', 0.4]));

// Anemones and the darks of every flower center: a chromatic black, never a tube black.
palette('petalWhite', mix(['white', 12], ['cadYellow', 0.2]));
palette('petalCool', mix(['white', 5], ['ultra', 0.3], ['alizarin', 0.15]));
palette('black', mix(['ultra', 1.2], ['alizarin', 0.9], ['umber', 1.2]));

// The lemon on the cloth.
palette('lemonLight', mix(['white', 2], ['cadYellow', 3]));
palette('lemon', mix(['cadYellow', 3], ['ochre', 0.6]));
palette('lemonShade', mix(['ochre', 2], ['umber', 0.5], ['alizarin', 0.12], ['viridian', 0.1]));

const W = canvas.width;
const H = canvas.height;
const TABLE = 975; // the table's back edge against the wall
const FRONT = 1385; // where the cloth turns down over the table's front edge
const JUG = { x: 560, lip: 818, base: 1215 };

/** The jug's half-width at height y: lip, neck, shoulder, belly, foot. */
function jugR(y) {
  const P = [
    [818, 112],
    [850, 90],
    [945, 160],
    [1075, 190],
    [1180, 170],
    [1215, 150],
  ];
  if (y <= P[0][0]) return P[0][1];
  for (let i = 1; i < P.length; i++) {
    if (y <= P[i][0]) {
      const t = (y - P[i - 1][0]) / (P[i][0] - P[i - 1][0]);
      const s = (1 - Math.cos(Math.PI * t)) / 2;
      return P[i - 1][1] + (P[i][1] - P[i - 1][1]) * s;
    }
  }
  return P[P.length - 1][1];
}

const FLOWERS = [
  { x: 430, y: 500, r: 122 },
  { x: 705, y: 385, r: 128 },
  { x: 285, y: 725, r: 98 },
  { x: 850, y: 640, r: 108 },
  { x: 545, y: 225, r: 102 },
  { x: 945, y: 405, r: 78 },
  { x: 200, y: 440, r: 74 },
  { x: 600, y: 610, r: 90 },
  { x: 760, y: 805, r: 78 },
  { x: 320, y: 280, r: 70 },
];

brush('scrub', { type: 'flat', width: 90, reservoir: 4, streak: 0.8 });
brush('scrubSmall', { type: 'flat', width: 40, reservoir: 2 });
brush('drawing', { type: 'round', width: 4, reservoir: 3 });

/** A loose stroke of length len from (x, y) at angle a, bowed a little. */
function sweep(x, y, a, len) {
  const c = Math.cos(a);
  const s = Math.sin(a);
  const bow = rand(-0.08, 0.08) * len;
  return [
    [x, y],
    [x + c * len * 0.5 - s * bow, y + s * len * 0.5 + c * bow],
    [x + c * len, y + s * len],
  ];
}

// The drawing: thin umber lines, the table edge, the jug's sides, each flower's circle.
const line = {
  brush: 'drawing',
  color: mix(['umber', 2], ['ultra', 0.5]),
  thinner: 0.5,
  load: 0.8,
};
stroke({
  ...line,
  path: [
    [-10, TABLE + 4],
    [400, TABLE],
    [800, TABLE - 3],
    [1210, TABLE - 8],
  ],
});
for (const side of [-1, 1]) {
  const pts = [];
  for (let y = JUG.lip; y <= JUG.base; y += 30) pts.push([JUG.x + side * jugR(y), y]);
  stroke({ ...line, path: pts });
}
for (const f of FLOWERS) {
  const pts = [];
  for (let a = 0; a <= Math.PI * 2.05; a += Math.PI / 6)
    pts.push([f.x + Math.cos(a) * f.r, f.y + Math.sin(a) * f.r * 0.85]);
  stroke({ ...line, path: pts, load: 0.5 });
}

// The wall: broad lean strokes, lightest toward the window at the upper left. Each stays
// above the table's edge.
for (let y = -20; y < TABLE - 20; y += 60) {
  for (let x = -60; x < W; x += rand(140, 220)) {
    const d = Math.hypot(x - 60, (y - 40) * 1.3) + rand(-90, 90);
    const pile = d < 380 ? 'wallLight' : d < 700 ? 'wallGold' : d < 1000 ? 'wallOlive' : 'wallDeep';
    const a = rand(0.3, 0.6);
    const len = Math.min(rand(180, 260), (TABLE - 40 - y) / Math.sin(a));
    stroke({
      path: sweep(x, y + rand(-10, 10), a, len),
      brush: 'scrub',
      color: pile,
      thinner: 0.6,
      load: 0.55,
    });
  }
}

// The cloth: level strokes, light toward the left, the front drop in shade.
for (let y = TABLE + 10; y < H + 30; y += 48) {
  for (let x = -60; x < W; x += rand(160, 230)) {
    const pile = y > FRONT ? 'clothShade' : x > 700 && y < 1300 ? 'clothMid' : 'clothLight';
    stroke({
      path: sweep(x, y + rand(-8, 8), rand(-0.06, 0.06), rand(200, 280)),
      brush: 'scrub',
      color: pile,
      thinner: 0.55,
      load: 0.55,
    });
  }
}

// The jug: its dark body scrubbed in across the curve of the belly.
for (let y = JUG.lip + 10; y < JUG.base; y += 26) {
  const r = jugR(y);
  stroke({
    path: sweep(JUG.x - r + 8, y, rand(-0.05, 0.05), 2 * r - 16),
    brush: 'scrubSmall',
    color: 'cobaltDeep',
    thinner: 0.5,
    load: 0.7,
  });
}

// The bouquet's dark: stems fanned up out of the jug's neck to each head.
for (const f of FLOWERS) {
  const sx = JUG.x + rand(-40, 40);
  const sy = JUG.lip + 10;
  stroke({
    path: [
      [sx, sy],
      [(sx + f.x) / 2 + rand(-30, 30), (sy + f.y) / 2],
      [f.x, f.y + f.r * 0.3],
    ],
    brush: { type: 'flat', width: rand(14, 24) },
    color: 'leafDark',
    thinner: 0.55,
    load: 0.6,
  });
}
FLOWERS.forEach((f, i) => {
  const stain =
    i >= 7 ? 'petalCool' : i % 3 === 0 ? 'redDark' : i % 3 === 1 ? 'orangeDark' : 'coralDark';
  for (let k = 0; k < 4; k++) {
    const y = f.y - f.r * 0.5 + k * f.r * 0.33;
    stroke({
      path: sweep(f.x - f.r * 0.7, y + rand(-6, 6), rand(-0.15, 0.15), f.r * 1.4),
      brush: 'scrubSmall',
      color: stain,
      thinner: 0.5,
      load: 0.6,
    });
  }
});

// Lean paint dries before the knife work goes over it.
dry();

/**
 * Passage 2: the wall, laid on with the palette knife.
 *
 * Broad knife planes go on in a first course, each pressed harder at one end than the
 * other so the paint stands up unevenly; a second course of smaller planes is pressed
 * straight into it while it is wet, scraping up and dragging the first course's color
 * so neighbouring piles smear into each other. The light from the window at the upper
 * left grades the wall from cream through ochre to a shaded olive, and the bouquet and
 * jug throw a cool shadow down to the right. The wall runs behind the flowers too; they
 * go over it later.
 */

const W = canvas.width;
const TABLE = 975;

const FLOWERS = [
  { x: 430, y: 500, r: 122 },
  { x: 705, y: 385, r: 128 },
  { x: 285, y: 725, r: 98 },
  { x: 850, y: 640, r: 108 },
  { x: 545, y: 225, r: 102 },
  { x: 945, y: 405, r: 78 },
  { x: 200, y: 440, r: 74 },
  { x: 600, y: 610, r: 90 },
  { x: 760, y: 805, r: 78 },
  { x: 320, y: 280, r: 70 },
];

/** How deep the shadow of the bouquet and the jug's lip lies at (x, y): 0 out of it, 1 deep in. */
function inShadow(x, y) {
  let s = 0;
  for (const f of FLOWERS) {
    const d = Math.hypot(x - f.x - 110, (y - f.y - 70) * 1.1) / f.r;
    s = Math.max(s, 1 - d);
  }
  // the jug's shoulder, low against the wall
  s = Math.max(s, 1 - Math.hypot(x - 790, (y - 930) * 1.6) / 200);
  return Math.min(1, s * 2);
}

/** The wall's pile at (x, y), from the window's light, wandering so the bands interlock. */
function wallPile(x, y) {
  const d = Math.hypot(x - 80, (y - 60) * 1.25) + 110 * noise(x / 150, y / 150) + rand(-50, 50);
  const lit = d < 330 ? 'wallLight' : d < 610 ? 'wallGold' : d < 900 ? 'wallOlive' : 'wallDeep';
  return inShadow(x, y) > 0.45 + rand(-0.15, 0.15) ? 'wallShadow' : lit;
}

/**
 * One knife plane from (x, y): a short, slightly bowed sweep at angle a, pressed hard at
 * one end and eased at the other. Its end is kept above the table's edge.
 */
function plane(x, y, a, len, width, color, load) {
  const c = Math.cos(a);
  const s = Math.sin(a);
  const cut = s > 0 ? Math.max(10, (TABLE - 8 - y) / s) : len;
  const L = Math.min(len, cut);
  const bow = rand(-0.12, 0.12) * L;
  const p0 = rand(0.5, 1);
  const p2 = rand(0.25, 0.9);
  stroke({
    path: [
      [x, y, p0],
      [x + c * L * 0.5 - s * bow, y + s * L * 0.5 + c * bow, Math.min(1, (p0 + p2) / 2 + 0.15)],
      [x + c * L, y + s * L, p2],
    ],
    brush: { type: 'knife', width, streak: rand(0.1, 0.35), toneVar: 0.35 },
    color,
    load,
    end: rand() < 0.4 ? 'stop' : 'lift',
  });
}

// First course: broad planes, mostly falling to the right with the light, row by row.
for (let y = -30; y < TABLE - 20; y += rand(38, 52)) {
  for (let x = -60; x < W + 20; x += rand(70, 120)) {
    const a = rand() < 0.75 ? rand(0.25, 0.75) : rand(-0.5, -0.1);
    const yy = y + rand(-15, 15);
    plane(x, yy, a, rand(90, 170), rand(46, 78), wallPile(x + 50, yy + 20), rand(0.8, 1));
  }
}

// Second course, wet into wet: smaller planes at cross angles that drag the first course.
for (let i = 0; i < 420; i++) {
  const x = rand(-30, W + 10);
  const y = rand(-20, TABLE - 25);
  const a = rand() < 0.5 ? rand(0.4, 1.1) : rand(-0.9, -0.2);
  plane(x, y, a, rand(45, 110), rand(26, 52), wallPile(x, y), rand(0.6, 0.95));
}

// The shadow's edge firmed with a few long cool planes along its upper side.
for (let i = 0; i < 70; i++) {
  const x = rand(560, W);
  const y = rand(200, TABLE - 40);
  const s = inShadow(x, y);
  if (s < 0.25 || s > 0.8) continue;
  plane(x, y, rand(0.6, 1.0), rand(60, 120), rand(24, 40), 'wallShadow', 0.9);
}

dry();

/**
 * Passage 3: the white cloth over the table.
 *
 * The cloth's top is laid in level knife planes, warm white where the window light
 * lands and greying toward the back right. Into that wet paint go the folds (a light
 * plane against a shaded one, run diagonally toward the front), the jug's cool shadow
 * thrown down to the right, and the drop over the table's front edge, where the cloth
 * hangs in vertical folds in shade. Last, the lit ridges get a thicker white.
 */

const W = canvas.width;
const H = canvas.height;
const TABLE = 975;
const FRONT = 1385;
const JUG = { x: 560, base: 1215 };

// Folds across the cloth's top: each runs from its back point toward the front.
const FOLDS = [
  { x0: 140, y0: 1030, x1: 290, y1: 1380 },
  { x0: 950, y0: 1010, x1: 1100, y1: 1380 },
];

/** How deep the jug's shadow lies at (x, y) on the cloth: 0 outside, 1 at the foot. */
function jugShadow(x, y) {
  const dx = x - JUG.x;
  if (dx < -150) return 0;
  const d = Math.hypot((x - 790) / 300, (y - 1238) / (48 + Math.max(0, dx) * 0.07));
  return Math.max(0, 1 - d) * (dx < 330 ? 1 : 0.7);
}

/** The cloth's pile at (x, y) on its top: light at the front left, greying to the back right. */
function clothPile(x, y) {
  if (jugShadow(x, y) > 0.35 + rand(-0.1, 0.1)) return x < 820 ? 'clothDeep' : 'clothShade';
  const d = x * 0.75 - (y - TABLE) * 0.45 + 130 * noise(x / 160, y / 70) + rand(-20, 20);
  // the bouquet's shadow lies across the back of the cloth on the right
  if (x > 700 && y < 1035 + rand(-10, 10)) return 'clothShade';
  return d < 420 ? 'clothLight' : d < 760 ? 'clothMid' : 'clothShade';
}

/** One knife plane: a bowed sweep with uneven pressure, its footprint kept in [top, bottom]. */
function plane(x, y, a, len, width, color, opts = {}) {
  const c = Math.cos(a);
  const s = Math.sin(a);
  const bow = rand(-0.1, 0.1) * len;
  const p0 = rand(0.5, 1);
  const p2 = rand(0.25, 0.9);
  stroke({
    path: [
      [x, y, p0],
      [x + c * len * 0.5 - s * bow, y + s * len * 0.5 + c * bow, Math.min(1, (p0 + p2) / 2 + 0.15)],
      [x + c * len, y + s * len, p2],
    ],
    brush: { type: 'knife', width, streak: rand(0.1, 0.3), toneVar: 0.3 },
    color,
    load: opts.load ?? rand(0.8, 1),
    end: rand() < 0.4 ? 'stop' : 'lift',
  });
}

// First course: level planes across the top, narrower toward the back where it recedes.
for (let y = TABLE + 6; y < FRONT - 6; y += rand(18, 30)) {
  const depth = (y - TABLE) / (FRONT - TABLE);
  for (let x = -60 - rand(100); x < W + 20; x += rand(60, 140)) {
    const w = (24 + depth * 34) * rand(0.7, 1.25);
    plane(x, y + rand(-7, 7), rand(-0.13, 0.13), rand(80, 200), w, clothPile(x + 60, y));
  }
}

// The folds, wet into wet: along each, a lit plane on its upper left, a shaded one below it.
for (const f of FOLDS) {
  const len = Math.hypot(f.x1 - f.x0, f.y1 - f.y0);
  const a = Math.atan2(f.y1 - f.y0, f.x1 - f.x0);
  const nx = -Math.sin(a);
  const ny = Math.cos(a);
  for (let t = 0; t < len - 30; t += rand(50, 80)) {
    const x = f.x0 + Math.cos(a) * t;
    const y = f.y0 + Math.sin(a) * t;
    const seg = Math.min(rand(70, 110), len - t);
    const j = rand(-6, 6);
    plane(
      x - nx * (14 + j),
      y - ny * (14 + j),
      a + rand(-0.1, 0.1),
      seg,
      rand(16, 30),
      'clothLight',
    );
    plane(
      x + nx * (12 + j),
      y + ny * (12 + j),
      a + rand(-0.1, 0.1),
      seg * rand(0.6, 1),
      rand(12, 26),
      jugShadow(x, y) > 0.2 ? 'clothShade' : 'clothMid',
      { load: rand(0.6, 0.85) },
    );
  }
}

// The jug's shadow: long planes laid along it, deepest against the foot.
for (let i = 0; i < 60; i++) {
  const x = rand(JUG.x - 80, 1150);
  const y = rand(1185, 1300);
  const s = jugShadow(x, y);
  if (s < 0.2) continue;
  plane(
    x - 40,
    y,
    rand(-0.12, 0.08),
    rand(70, 140),
    rand(16, 30),
    s > 0.55 && x < 820 ? 'clothDeep' : 'clothShade',
  );
}
// the dark where the foot meets the cloth
stroke({
  path: [
    [JUG.x - 140, JUG.base - 2, 0.6],
    [JUG.x, JUG.base + 4, 1],
    [JUG.x + 150, JUG.base - 2, 0.8],
  ],
  brush: { type: 'knife', width: 12 },
  color: mix(['clothDeep', 2], ['cobaltDeep', 1]),
  load: 0.9,
});

// The drop over the front edge: vertical planes in shade, the folds lighter on their ridges.
/** How far up a fold's ridge x lies on the hanging cloth, 0 in a hollow to 1 on a ridge. */
const ridge = (x) => 0.5 + 0.5 * Math.sin(x / 95 + noise(x / 200, 3) * 2);
const dropPile = (x) => {
  const r = ridge(x) + rand(-0.15, 0.15);
  return r > 0.7 ? 'clothMid' : r < 0.25 ? 'clothDeep' : 'clothShade';
};
for (let x = -30; x < W + 30; x += rand(28, 60)) {
  plane(
    x + rand(-6, 6),
    FRONT + 18,
    Math.PI / 2 + rand(-0.08, 0.08),
    H - FRONT,
    rand(28, 50),
    dropPile(x),
  );
}
// and shorter planes pushed into them wet, so the folds turn instead of striping
for (let i = 0; i < 70; i++) {
  const x = rand(-20, W + 20);
  plane(
    x,
    rand(FRONT + 20, H - 40),
    Math.PI / 2 + rand(-0.2, 0.2),
    rand(40, 90),
    rand(18, 34),
    dropPile(x),
    { load: rand(0.6, 0.9) },
  );
}
// the cloth rolling over the edge catches the light in one long ridge
for (let x = -40; x < W; x += rand(120, 180)) {
  const lit = x < 750;
  plane(
    x,
    FRONT + rand(-4, 4),
    rand(-0.03, 0.03),
    rand(150, 220),
    rand(16, 22),
    lit ? 'clothLight' : 'clothMid',
  );
}

// Thicker whites on the lit side of the cloth, the last and heaviest paint here.
for (let i = 0; i < 40; i++) {
  const x = rand(-20, 720);
  const y = rand(TABLE + 40, FRONT - 20);
  if (jugShadow(x, y) > 0 || Math.abs(x - JUG.x) < 200) continue;
  plane(x, y, rand(-0.1, 0.1), rand(50, 100), rand(18, 34), 'clothLight', { load: 1 });
}

dry();

/**
 * Passage 4: the cobalt jug.
 *
 * The knife goes down the jug in curved planes that follow its belly, each column
 * taking the pile its side of the form wants: light on the left toward the window,
 * deep on the right, and a warm reflected light low on the right edge from the cloth.
 * The shoulder is turned with short planes across it. Then, still wet, the highlights
 * are pressed on thick with the knife's tip, the rim is drawn as one bright curve, and
 * the handle is pulled out from the shoulder in a single loop.
 */

const JUG = { x: 560, lip: 818, base: 1215 };

/** The jug's half-width at height y: lip, neck, shoulder, belly, foot. */
function jugR(y) {
  const P = [
    [818, 112],
    [850, 90],
    [945, 160],
    [1075, 190],
    [1180, 170],
    [1215, 150],
  ];
  if (y <= P[0][0]) return P[0][1];
  for (let i = 1; i < P.length; i++) {
    if (y <= P[i][0]) {
      const t = (y - P[i - 1][0]) / (P[i][0] - P[i - 1][0]);
      const s = (1 - Math.cos(Math.PI * t)) / 2;
      return P[i - 1][1] + (P[i][1] - P[i - 1][1]) * s;
    }
  }
  return P[P.length - 1][1];
}

/** The pile for a point on the jug at u (-1 left edge to 1 right) and height y. */
function jugPile(u, y) {
  const top = y < 960 ? 0.25 : 0; // the shoulder faces up into the light
  // the wobble is noise across the surface, so neighbouring planes agree and facets read
  const lit = -u + top + 0.35 * noise(u * 2.5, y / 70) + rand(-0.1, 0.1);
  if (u > 0.78 && y > 1000) return 'jugWarm';
  return lit > 0.5 ? 'cobaltLight' : lit > -0.15 ? 'cobalt' : 'cobaltDeep';
}

/** A knife stroke down the jug's surface along u, from y0 to y1, kept inside its silhouette. */
function meridian(u, y0, y1, width, color, load = 0.9) {
  const pts = [];
  for (let k = 0; k <= 4; k++) {
    const y = y0 + ((y1 - y0) * k) / 4;
    const r = jugR(y);
    const uu = Math.max(-1, Math.min(1, u)) * Math.max(0, 1 - width / 2 / r);
    pts.push([JUG.x + uu * r, y, rand(0.45, 1)]);
  }
  stroke({
    path: pts,
    brush: { type: 'knife', width, streak: rand(0.1, 0.3), toneVar: 0.3 },
    color,
    load,
    end: rand() < 0.5 ? 'stop' : 'lift',
  });
}

// The body: overlapping columns of curved planes, top to bottom in two or three lengths each.
for (let pass = 0; pass < 2; pass++) {
  for (let u = -0.95; u <= 0.95; u += rand(0.12, 0.18)) {
    let y = 845 + rand(0, 40) + pass * 30;
    for (let y1 = 0; y1 < 1205; y = y1 - rand(10, 30)) {
      y1 = Math.min(1205, y + rand(170, 330));
      meridian(u + rand(-0.04, 0.04), y, y1, rand(26, 40), jugPile(u, (y + y1) / 2));
    }
  }
}

// Round the belly, wet into the columns: arcs that sag toward us, since the eye is above the
// jug, lightly loaded so they drag the columns' colors across each other.
for (let y = 960; y < 1195; y += rand(20, 34)) {
  const r = jugR(y);
  for (let u = -0.92 + rand(0.2); u < 0.8; u += rand(0.4, 0.6)) {
    const u1 = Math.min(0.92, u + rand(0.35, 0.55));
    const sag = (y - 900) * 0.09;
    const at = (v) => [JUG.x + v * (r - 10), y + sag * (1 - v * v), rand(0.4, 0.9)];
    stroke({
      path: [at(u), at((u + u1) / 2), at(u1)],
      brush: { type: 'knife', width: rand(16, 28), streak: 0.25, toneVar: 0.3 },
      color: jugPile((u + u1) / 2, y),
      load: rand(0.5, 0.75),
    });
  }
}

// The shoulder turned across: short planes curving round it.
for (let y = 870; y < 980; y += rand(18, 26)) {
  const r = jugR(y);
  for (let u = -0.9; u < 0.7; u += rand(0.35, 0.5)) {
    const x0 = JUG.x + u * r;
    const x1 = JUG.x + Math.min(0.9, u + rand(0.3, 0.45)) * r;
    const sag = 10 * (1 - Math.abs((u + 0.2) / 1.2));
    stroke({
      path: [
        [x0, y, rand(0.5, 1)],
        [(x0 + x1) / 2, y + sag, 1],
        [x1, y, rand(0.4, 0.9)],
      ],
      brush: { type: 'knife', width: rand(18, 26), streak: 0.2, toneVar: 0.3 },
      color: jugPile(u + 0.2, y),
      load: 0.85,
    });
  }
}

// The neck and the rim: a dark band under a bright curved lip.
for (let y = 828; y < 870; y += 12) {
  const r = jugR(y);
  stroke({
    path: [
      [JUG.x - r + 10, y],
      [JUG.x, y + 8],
      [JUG.x + r - 10, y],
    ],
    brush: { type: 'knife', width: 16 },
    color: y < 845 ? 'cobalt' : 'cobaltDeep',
    load: 0.9,
  });
}
stroke({
  path: [
    [JUG.x - 110, 818, 0.8],
    [JUG.x - 40, 830, 1],
    [JUG.x + 50, 829, 0.8],
    [JUG.x + 108, 816, 0.5],
  ],
  brush: { type: 'knife', width: 9 },
  color: 'cobaltLight',
  load: 1,
  end: 'stop',
});

// The handle: one loop pulled from the shoulder, then its lit top edge.
const HANDLE = [
  [JUG.x + 150, 905],
  [JUG.x + 215, 915],
  [JUG.x + 248, 975],
  [JUG.x + 232, 1045],
  [JUG.x + 186, 1085],
];
stroke({
  path: HANDLE,
  brush: { type: 'knife', width: 36 },
  color: 'cobaltDeep',
  load: 1,
  end: 'stop',
});
stroke({
  path: HANDLE.slice(0, 4).map(([x, y]) => [x - 2, y - 9, 0.8]),
  brush: { type: 'knife', width: 13 },
  color: 'cobaltLight',
  load: 0.8,
});

// Highlights, thick and wet into the blue: the window on the shoulder, a softer one below.
const GLINTS = [
  { x: JUG.x - 98, y0: 888, y1: 950, w: 15, c: 'jugGlint' },
  { x: JUG.x - 118, y0: 975, y1: 1085, w: 12, c: 'cobaltLight' },
  { x: JUG.x - 127, y0: 1000, y1: 1050, w: 7, c: 'jugGlint' },
  { x: JUG.x - 62, y0: 900, y1: 925, w: 8, c: 'jugGlint' },
];
for (const g of GLINTS) {
  stroke({
    path: [
      [g.x + 4, g.y0, 0.7],
      [g.x - 2, (g.y0 + g.y1) / 2, 1],
      [g.x - 6, g.y1, 0.6],
    ],
    brush: { type: 'knife', width: g.w },
    color: g.c,
    load: 1,
    end: 'stop',
  });
}

dry();

/**
 * Passage 5: the foliage, stems, and buds.
 *
 * The bouquet's mass goes in first: clumps of short, broad knife planes in the dark
 * green, packed round the jug's mouth and under each flower head, turning grey-green
 * where they face the window and darkest low on the right. The stems are drawn over it
 * with the knife's edge, a fine blade dragged up from the neck to each head and lit on
 * its left. A few long blades break the bouquet's outline, and the nodding buds go on
 * as a cluster of small planes each, wet, with a lit edge.
 */

const JUG = { x: 560, lip: 818 };

const FLOWERS = [
  { x: 430, y: 500, r: 122 },
  { x: 705, y: 385, r: 128 },
  { x: 285, y: 725, r: 98 },
  { x: 850, y: 640, r: 108 },
  { x: 545, y: 225, r: 102 },
  { x: 945, y: 405, r: 78 },
  { x: 200, y: 440, r: 74 },
  { x: 600, y: 610, r: 90 },
  { x: 760, y: 805, r: 78 },
  { x: 320, y: 280, r: 70 },
];
// Nodding buds: where each hangs and which way its stem hooks over.
const BUDS = [
  { x: 190, y: 190, hook: -1 },
  { x: 1050, y: 590, hook: 1 },
  { x: 860, y: 170, hook: 1 },
];

/** The pile at (x, y): grey-green toward the window, dark low on the right. */
function greenPile(x, y) {
  const lit = -(x - 560) / 600 - (y - 520) / 450 + 0.5 * noise(x / 90, y / 90) + rand(-0.25, 0.25);
  return lit > 0.6 ? 'leafGrey' : lit > -0.1 ? 'leaf' : 'leafDark';
}

/** A short broad knife plane at angle a, pressed hard and lifted. */
function plane(x, y, a, len, width, color, load = rand(0.8, 1)) {
  const c = Math.cos(a);
  const s = Math.sin(a);
  const curl = rand(-0.15, 0.15) * len;
  stroke({
    path: [
      [x, y, rand(0.7, 1)],
      [x + c * len * 0.55 - s * curl, y + s * len * 0.55 + c * curl, rand(0.6, 1)],
      [x + c * len, y + s * len, rand(0.2, 0.6)],
    ],
    brush: { type: 'knife', width, streak: 0.3, toneVar: 0.4 },
    color,
    load,
    end: rand() < 0.3 ? 'stop' : 'lift',
  });
}

/**
 * A clump of planes radiating from (x, y) within radius r: packed and dark in its middle,
 * the outer planes in the middle green so the clump's edge sits softly on the wall.
 */
function clump(x, y, r, n) {
  for (let i = 0; i < n; i++) {
    const a = rand(Math.PI * 2);
    const d = r * Math.sqrt(rand());
    const px = x + Math.cos(a) * d;
    const py = y + Math.sin(a) * d;
    const pile = greenPile(px, py);
    plane(
      px,
      py,
      a + rand(-0.6, 0.6),
      rand(26, 60),
      rand(20, 34),
      d > r * 0.7 && pile === 'leafDark' ? 'leaf' : pile,
    );
  }
}

// The mass: a nest spilling over the jug's lip, and clumps under and between the heads.
clump(JUG.x + 10, JUG.lip - 50, 170, 110);
for (const f of FLOWERS) {
  for (let k = 0; k < 3; k++) {
    const a = Math.PI / 2 + rand(-1.4, 1.4);
    clump(f.x + Math.cos(a) * f.r * 0.85, f.y + Math.sin(a) * f.r * 0.85, f.r * 0.55, 16);
  }
}

// Stems: the knife's edge dragged from the neck to each head and bud, then its lit side.
const tips = [
  ...FLOWERS.map((f) => [f.x, f.y + f.r * 0.3]),
  ...BUDS.map((b) => [b.x - b.hook * 30, b.y - 40]),
];
for (const [x, y] of tips) {
  const x0 = JUG.x + (x - JUG.x) * 0.15 + rand(-20, 20);
  const y0 = JUG.lip + 4;
  const p = [
    [x0, y0],
    [(x0 + x) / 2 + (x - JUG.x) * 0.25, (y0 + y) / 2 + 30],
    [x, y],
  ];
  stroke({ path: p, brush: { type: 'knife', width: rand(6, 9) }, color: 'stem', load: 0.9 });
  stroke({
    path: p.map(([px, py]) => [px - 2.5, py - 1]),
    brush: { type: 'knife', width: 2.5 },
    color: 'leafGrey',
    load: 0.8,
  });
}

// Long blades breaking the outline, mostly at the sides and low around the lip.
for (let i = 0; i < 26; i++) {
  const side = i % 2 ? 1 : -1;
  const x = JUG.x + side * rand(120, 380);
  const y = rand(560, 830);
  const a = (side > 0 ? 0 : Math.PI) + side * rand(-0.9, 0.2);
  plane(x, y, a, rand(60, 110), rand(12, 18), greenPile(x + Math.cos(a) * 40, y));
}

// Buds: a hooked stem, then a cluster of small planes down the bud and a lit edge.
for (const b of BUDS) {
  stroke({
    path: [
      [b.x - b.hook * 30, b.y - 40],
      [b.x - b.hook * 8, b.y - 54],
      [b.x, b.y - 24],
    ],
    brush: { type: 'knife', width: 6 },
    color: 'stem',
    load: 0.9,
  });
  for (let k = 0; k < 6; k++) {
    const t = k / 5;
    const off = Math.sin(t * Math.PI) * 9 * (k % 2 ? 1 : -1);
    stroke({
      path: [
        [b.x + off * 0.4, b.y - 22 + t * 4, 0.7],
        [b.x + off + b.hook * 3, b.y - 2 + t * 6, 1],
        [b.x + off * 0.5 + b.hook * 4, b.y + 18, 0.5],
      ],
      brush: { type: 'knife', width: rand(9, 13) },
      color: off < 0 ? 'leafGrey' : k % 3 ? 'leaf' : 'leafDark',
      load: 0.95,
    });
  }
  stroke({
    path: [
      [b.x - 8, b.y - 16, 0.6],
      [b.x - 10, b.y + 8, 0.9],
    ],
    brush: { type: 'knife', width: 3.5 },
    color: mix(['leafGrey', 2], ['white', 1]),
    load: 0.9,
  });
}

dry();

/**
 * Passage 6: the poppies, each petal laid with the knife from the heart out to the rim.
 *
 * A poppy is a cup of four or five petals. Each petal goes on as a fan of knife strokes
 * pulled outward from near the center and stopped at the rim, so the paint piles into a
 * ridge where the blade halts, the way a petal's edge curls. The cup is lit from the
 * window: the inner faces of the petals on the far side (lower right) turn to the light,
 * the near ones (upper left) fall into the cup's shade, and their curled rims catch it.
 * Body color first, then light and dark pressed into it wet; then each heart, a dark ring
 * of stamens round a grey-green seed head.
 */

const LIGHT = { x: -0.63, y: -0.77 };

// kind picks the pile family; tilt and squash foreshorten the cup.
const POPPIES = [
  { x: 545, y: 225, r: 102, kind: 'orange', tilt: 0.3, squash: 0.85, petals: 5 },
  { x: 705, y: 385, r: 128, kind: 'orange', tilt: -0.3, squash: 0.9, petals: 5 },
  { x: 945, y: 405, r: 78, kind: 'coral', tilt: -0.5, squash: 0.75, petals: 4 },
  { x: 200, y: 440, r: 74, kind: 'red', tilt: 0.5, squash: 0.8, petals: 4 },
  { x: 430, y: 500, r: 122, kind: 'red', tilt: 0.1, squash: 0.92, petals: 5 },
  { x: 850, y: 640, r: 108, kind: 'red', tilt: -0.75, squash: 0.62, petals: 5 },
  { x: 285, y: 725, r: 98, kind: 'coral', tilt: 0.6, squash: 0.72, petals: 4 },
];

const PILES = {
  red: ['redDark', 'red', 'redLight'],
  orange: ['orangeDark', 'orange', 'orangeLight'],
  coral: ['coralDark', 'coral', 'coralLight'],
};

/** Map a point on the flat flower (dx, dy from center) onto the canvas, foreshortened. */
function place(f, dx, dy) {
  const c = Math.cos(f.tilt);
  const s = Math.sin(f.tilt);
  const u = dx * c + dy * s;
  const v = (-dx * s + dy * c) * f.squash;
  return [f.x + u * c - v * s, f.y + u * s + v * c];
}

/** One knife pull along a petal at angle th, from radius r0 to r1, bowed by `bow`. */
function pull(f, th, r0, r1, width, color, opts = {}) {
  const bow = opts.bow ?? rand(-0.12, 0.12);
  const pts = [0, 0.5, 1].map((t) => {
    const r = r0 + (r1 - r0) * t;
    const a = th + bow * Math.sin(Math.PI * t);
    const [x, y] = place(f, Math.cos(a) * r, Math.sin(a) * r);
    return [x, y, t === 0 ? 0.55 : t === 0.5 ? 1 : rand(0.7, 1)];
  });
  stroke({
    path: pts,
    brush: { type: 'knife', width, streak: rand(0.1, 0.3), toneVar: 0.35 },
    color,
    load: opts.load ?? rand(0.85, 1),
    end: opts.end ?? 'stop',
  });
}

for (const f of POPPIES) {
  const [dark, body, light] = PILES[f.kind];
  const start = rand(Math.PI * 2);
  const step = (Math.PI * 2) / f.petals;
  const petals = [];
  for (let k = 0; k < f.petals; k++) {
    const th = start + k * step + rand(-0.15, 0.15);
    // the cup's inner face looks back toward the light from the far side
    const facing = -(Math.cos(th) * LIGHT.x + Math.sin(th) * LIGHT.y);
    petals.push({ th, facing, reach: f.r * rand(0.88, 1.05) });
  }

  // body color: a fan of four pulls per petal, overlapping its neighbours, the far petals first
  petals.sort((a, b) => a.facing - b.facing);
  for (const p of petals) {
    for (const off of [-0.42, -0.14, 0.14, 0.42]) {
      pull(
        f,
        p.th + off * step,
        f.r * 0.12,
        p.reach * (1 - Math.abs(off) * 0.2),
        f.r * rand(0.34, 0.46),
        body,
      );
    }
  }
  // light and shade pressed into the wet body
  for (const p of petals) {
    const pile = p.facing > 0.25 ? light : p.facing < -0.35 ? dark : null;
    if (pile) {
      pull(f, p.th + rand(-0.15, 0.15), f.r * 0.25, p.reach * 0.9, f.r * rand(0.28, 0.38), pile, {
        load: rand(0.7, 0.9),
      });
    }
    // the deep of the cup, dragged out from the heart
    pull(f, p.th + rand(-0.4, 0.4), f.r * 0.05, f.r * rand(0.35, 0.5), f.r * 0.2, dark, {
      load: 0.8,
      end: 'lift',
    });
  }
  // each petal's rim swept round in one curved pull, which rounds off the square ends of
  // the outward strokes; the curled rims of the near petals catch the window
  for (const p of petals) {
    const near = p.facing < -0.2;
    const a0 = p.th - step * 0.5;
    const a1 = p.th + step * 0.5;
    const rr = p.reach * 0.9;
    const pts = [a0, p.th - step * 0.2, p.th + step * 0.2, a1].map((a) => {
      const [x, y] = place(
        f,
        Math.cos(a) * rr * (1 - 0.1 * Math.abs(a - p.th)),
        Math.sin(a) * rr * (1 - 0.1 * Math.abs(a - p.th)),
      );
      return [x, y, rand(0.5, 1)];
    });
    stroke({
      path: pts,
      brush: { type: 'knife', width: f.r * (near ? 0.12 : 0.18), streak: 0.2 },
      color: near ? light : body,
      load: 0.9,
      end: 'stop',
    });
  }

  // the seams where one petal tucks under the next: the knife's edge drawn out in the dark
  for (const p of petals) {
    const a = p.th + step * 0.5 + rand(-0.08, 0.08);
    pull(f, a, f.r * 0.2, f.r * rand(0.75, 0.9), 3.5, dark, {
      load: 0.9,
      end: 'lift',
      bow: rand(-0.05, 0.05),
    });
  }

  // the heart: a ring of dark stamens, then the seed head with its lit top
  const ring = Math.round(f.r * 0.22);
  for (let k = 0; k < ring; k++) {
    const a = (k / ring) * Math.PI * 2 + rand(-0.1, 0.1);
    const rr = f.r * rand(0.13, 0.22);
    const [x, y] = place(f, Math.cos(a) * rr, Math.sin(a) * rr);
    stroke({
      path: [[x, y]],
      brush: { type: 'knife', width: rand(4, 7) },
      color: 'black',
      load: 0.9,
      angle: a,
    });
  }
  const [hx, hy] = place(f, 0, 0);
  stroke({
    path: [
      [hx - f.r * 0.08, hy - 2],
      [hx + f.r * 0.08, hy + 2],
    ],
    brush: { type: 'knife', width: f.r * 0.13 },
    color: 'leaf',
    load: 1,
    end: 'stop',
  });
  stroke({
    path: [
      [hx - f.r * 0.07, hy - f.r * 0.04],
      [hx + f.r * 0.02, hy - f.r * 0.05],
    ],
    brush: { type: 'knife', width: 4 },
    color: 'leafGrey',
    load: 1,
  });
  // pollen on a few stamens
  for (let k = 0; k < ring / 3; k++) {
    const a = rand(Math.PI * 2);
    const rr = f.r * rand(0.15, 0.24);
    const [x, y] = place(f, Math.cos(a) * rr, Math.sin(a) * rr);
    stroke({
      path: [[x, y]],
      brush: { type: 'knife', width: 3 },
      color: 'lemonLight',
      load: 0.9,
      angle: a,
    });
  }
}

dry();

/**
 * Passage 7: the white anemones, the lemon and fallen petals, and the last thick lights.
 *
 * Each anemone is six rounded petals, warm white where they face the window and cool
 * where they turn from it, laid with the knife like the poppies and finished with a
 * black heart and a ring of stamens. On the cloth, a lemon is turned in curved planes
 * over its own small shadow, and two fallen petals lie in front of the jug. Last, the
 * heaviest paint in the picture: the window's highlight on the jug and a few lights on
 * the wall and cloth, pressed on with a fully loaded knife and left standing.
 */

const LIGHT = { x: -0.63, y: -0.77 };
const JUG = { x: 560 };

const ANEMONES = [
  { x: 600, y: 610, r: 90, tilt: -0.2, squash: 0.85 },
  { x: 760, y: 805, r: 78, tilt: 0.4, squash: 0.68 },
  { x: 320, y: 280, r: 70, tilt: 0.2, squash: 0.8 },
];

/** Map a point on the flat flower (dx, dy from center) onto the canvas, foreshortened. */
function place(f, dx, dy) {
  const c = Math.cos(f.tilt);
  const s = Math.sin(f.tilt);
  const u = dx * c + dy * s;
  const v = (-dx * s + dy * c) * f.squash;
  return [f.x + u * c - v * s, f.y + u * s + v * c];
}

/** A knife stroke through points given in the flower's own polar terms [angle, radius, pressure]. */
function polar(f, pts, width, color, opts = {}) {
  stroke({
    path: pts.map(([a, r, p]) => [...place(f, Math.cos(a) * r, Math.sin(a) * r), p]),
    brush: { type: 'knife', width, streak: opts.streak ?? 0.2, toneVar: 0.3 },
    color,
    load: opts.load ?? 0.95,
    end: opts.end ?? 'stop',
  });
}

for (const f of ANEMONES) {
  const start = rand(Math.PI * 2);
  const step = (Math.PI * 2) / 6;
  for (let k = 0; k < 6; k++) {
    const th = start + k * step + rand(-0.1, 0.1);
    const facing = Math.cos(th) * LIGHT.x + Math.sin(th) * LIGHT.y;
    const pile =
      facing > 0.2
        ? 'petalWhite'
        : facing < -0.4
          ? 'petalCool'
          : mix(['petalWhite', 1], ['petalCool', 1]);
    const reach = f.r * rand(0.9, 1.02);
    for (const off of [-0.3, 0, 0.3]) {
      const a = th + off * step;
      polar(
        f,
        [
          [a, f.r * 0.15, 0.6],
          [a + rand(-0.08, 0.08), reach * 0.55, 1],
          [a, reach * (1 - Math.abs(off) * 0.2), rand(0.6, 1)],
        ],
        f.r * 0.34,
        pile,
      );
    }
    // the rounded rim, swept across the petal's end
    polar(
      f,
      [
        [th - step * 0.45, reach * 0.82, 0.6],
        [th, reach * 0.95, 1],
        [th + step * 0.45, reach * 0.82, 0.7],
      ],
      f.r * 0.16,
      facing > 0.2 ? mix(['petalWhite', 3], ['white', 1]) : pile,
      { load: 0.9 },
    );
  }
  // a shadow pressed into the wet whites round the heart, then the black heart
  for (let k = 0; k < 5; k++) {
    const a = rand(Math.PI * 2);
    polar(
      f,
      [
        [a, f.r * 0.15, 0.8],
        [a, f.r * 0.42, 0.4],
      ],
      f.r * 0.16,
      'petalCool',
      { load: 0.7, end: 'lift' },
    );
  }
  for (let k = 0; k < 3; k++) {
    const a = rand(Math.PI);
    polar(
      f,
      [
        [a, f.r * 0.14, 0.9],
        [a + Math.PI, f.r * 0.14, 0.9],
      ],
      f.r * 0.13,
      'black',
      { load: 1 },
    );
  }
  const n = Math.round(f.r * 0.28);
  for (let k = 0; k < n; k++) {
    const a = (k / n) * Math.PI * 2 + rand(-0.12, 0.12);
    const [x, y] = place(
      f,
      Math.cos(a) * f.r * rand(0.22, 0.3),
      Math.sin(a) * f.r * rand(0.22, 0.3),
    );
    stroke({
      path: [[x, y]],
      brush: { type: 'knife', width: rand(3.5, 6) },
      color: 'black',
      load: 0.9,
      angle: a,
    });
  }
  const [hx, hy] = place(f, -f.r * 0.05, -f.r * 0.06);
  stroke({ path: [[hx, hy]], brush: { type: 'knife', width: 5 }, color: 'petalCool', load: 1 });
}

// The lemon: its shadow on the cloth, then planes turned along its length, lit top left.
const LEMON = { x: 935, y: 1272, rx: 64, ry: 42, a: -0.22 };
const lc = Math.cos(LEMON.a);
const ls = Math.sin(LEMON.a);
const onLemon = (u, v) => [
  LEMON.x + u * LEMON.rx * lc - v * LEMON.ry * ls,
  LEMON.y + u * LEMON.rx * ls + v * LEMON.ry * lc,
];
for (let k = 0; k < 4; k++) {
  stroke({
    path: [
      [LEMON.x - 30, LEMON.y + 34 + k * 5],
      [LEMON.x + 40, LEMON.y + 40 + k * 4],
      [LEMON.x + 110, LEMON.y + 26 + k * 3],
    ],
    brush: { type: 'knife', width: 16 },
    color: k < 2 ? 'clothDeep' : 'clothShade',
    load: 0.85,
  });
}
for (let v = -0.8; v <= 0.81; v += 0.32) {
  const span = Math.sqrt(1 - v * v) * 0.95;
  const pile = v < -0.4 ? 'lemonLight' : v > 0.5 ? 'lemonShade' : 'lemon';
  stroke({
    path: [onLemon(-span, v + 0.12), onLemon(0, v), onLemon(span, v + 0.12)].map(([x, y]) => [
      x,
      y,
      rand(0.6, 1),
    ]),
    brush: { type: 'knife', width: 19, streak: 0.2, toneVar: 0.3 },
    color: pile,
    load: 0.95,
  });
}
for (const u of [-1.08, 1.08]) {
  stroke({
    path: [onLemon(u, 0)],
    brush: { type: 'knife', width: 9 },
    color: 'lemon',
    load: 0.9,
    angle: LEMON.a,
  });
}
stroke({
  path: [onLemon(-0.35, -0.55), onLemon(0.1, -0.62)],
  brush: { type: 'knife', width: 6 },
  color: 'white',
  load: 1,
  end: 'stop',
});

// Fallen petals in front of the jug, each over a sliver of its own shadow.
const FALLEN = [
  { x: 370, y: 1300, a: 0.35, piles: ['red', 'redLight'] },
  { x: 705, y: 1350, a: -0.5, piles: ['orange', 'orangeLight'] },
];
for (const p of FALLEN) {
  const c = Math.cos(p.a);
  const s = Math.sin(p.a);
  stroke({
    path: [
      [p.x - c * 26 + 5, p.y - s * 26 + 9],
      [p.x + c * 26 + 5, p.y + s * 26 + 9],
    ],
    brush: { type: 'knife', width: 20 },
    color: 'clothShade',
    load: 0.8,
  });
  // a cupped petal: its body, then the lit inner curve pressed into it wet
  [0, 1, 2].forEach((k) => {
    const cup = 10 - k * 6;
    stroke({
      path: [
        [p.x - c * 34, p.y - s * 34 - k * 4, 0.6],
        [p.x + s * cup, p.y - c * cup - k * 4, 1],
        [p.x + c * 32, p.y + s * 32 - k * 4, 0.8],
      ],
      brush: { type: 'knife', width: k === 2 ? 10 : 22, streak: 0.2 },
      color: p.piles[k === 2 ? 1 : 0],
      load: 0.95,
      end: 'stop',
    });
  });
}

// The last lights, thick: the window on the jug's shoulder, the wall where the light lands,
// and the lit ridge of the cloth.
stroke({
  path: [
    [JUG.x - 94, 892, 0.7],
    [JUG.x - 100, 915, 1],
    [JUG.x - 104, 940, 0.8],
  ],
  brush: { type: 'knife', width: 10 },
  color: 'jugGlint',
  load: 1,
  end: 'stop',
});
const brightWall = mix(['wallLight', 3], ['white', 1]);
for (let i = 0; i < 14; i++) {
  const x = rand(0, 300);
  const y = rand(0, 260);
  if (Math.hypot(x - 320, y - 280) < 120) continue; // clear of the anemone
  const a = rand(0.3, 0.7);
  stroke({
    path: [
      [x, y, rand(0.6, 1)],
      [x + Math.cos(a) * 50, y + Math.sin(a) * 50, 1],
      [x + Math.cos(a) * 95, y + Math.sin(a) * 95, rand(0.3, 0.8)],
    ],
    brush: { type: 'knife', width: rand(26, 44), streak: 0.25, toneVar: 0.3 },
    color: brightWall,
    load: 1,
    end: 'stop',
  });
}
const brightCloth = mix(['clothLight', 3], ['white', 1]);
for (let i = 0; i < 10; i++) {
  const x = rand(20, 300);
  const y = rand(1060, 1360);
  stroke({
    path: [
      [x, y, 0.8],
      [x + 50, y + rand(-3, 3), 1],
      [x + rand(80, 120), y + rand(-4, 4), 0.5],
    ],
    brush: { type: 'knife', width: rand(16, 28), streak: 0.2 },
    color: brightCloth,
    load: 1,
    end: 'stop',
  });
}
